use std::{env,fs,process}; use caveat_runtime::{eval,parser,NodeKind};
fn main(){let path=env::args().nth(1).unwrap_or_else(||{eprintln!("usage: caveat <file.cav>");process::exit(2)});let source=fs::read_to_string(&path).unwrap_or_else(|e|{eprintln!("caveat: {e}");process::exit(1)});let p=parser::parse(&source).unwrap_or_else(|e|{eprintln!("parse error: {e}");process::exit(1)});let r=eval::evaluate(&p).unwrap_or_else(|e|{eprintln!("evaluation error: {e}");process::exit(1)});println!("CAVEAT: {} statements -> {} graph nodes, {} edges, {} history events",p.statements.len(),r.graph.nodes.len(),r.graph.edges.len(),r.history.len());if let Some(b)=&r.resources{println!("resources: initial={} spent={} remaining={} exhausted={}",b.initial,b.spent,b.remaining,b.exhausted)}for(name,id)in&r.symbols{if let Some(NodeKind::Commitment{open,stop_reason,..})=r.graph.nodes.get(id){println!("commit {name}: open={open} stop={stop_reason:?}")}}for e in&r.history{println!("event {}: {:?}",e.sequence,e.kind)}}
